# sqa_name_surface_forms
import re

_CAP = re.compile(r"\b([A-Z][a-z]+)\s+([A-Z][a-z]+)(?:\s+([A-Z][a-z]+))?\b")
_STOP = frozenset([
    "The", "A", "An", "This", "That", "These", "Those", "His", "Her",
    "Its", "Their", "Our", "My", "Your", "Which", "What", "Who", "Whom",
    "Whose", "Where", "When", "Why", "How", "In", "On", "At", "To", "For",
    "From", "Of", "With", "By", "As", "And", "But", "Or", "Not", "No",
    "All", "Both", "Each", "Few", "More", "Most", "Some", "Such", "Only",
    "First", "Last", "New", "Old", "North", "South", "East", "West"
])


def _count_whole(ctx, form):
    pat = re.compile(r"\b" + re.escape(form) + r"\b")
    return len(pat.findall(ctx))


def _find_name(q):
    for m in _CAP.finditer(q):
        words = [w for w in m.groups() if w]
        if words and words[0] not in _STOP:
            return words
    return None


def applies(view):
    q = view.get("question", "")
    return _find_name(q) is not None


def before_call(view, state):
    q = view.get("question", "")
    ctx = view.get("context", "")
    words = _find_name(q)
    if not words:
        return None
    full = " ".join(words)
    forms = set([full])
    if len(words) >= 2:
        forms.add(words[0])
        forms.add(words[-1])
        if len(words) == 3:
            forms.add(words[0] + " " + words[1])
    table = []
    for f in sorted(forms):
        c = _count_whole(ctx, f)
        if c:
            table.append([f[:40], str(c)])
    if not table:
        return None
    facts = [("Question contains the capitalized phrase '%s'; whole-word (word-boundary) occurrence counts of its surface forms in the snippets:" % full[:100])[:200]]
    return {"facts": facts, "table": table[:8]}
